/* =============================================================================
   Theraglee — Discover: 360 free self-discovery tools, twenty per topic.
   -----------------------------------------------------------------------------
   Every visitor can use all of these, signed in or not. They help people notice
   their own patterns; none of them diagnoses, screens for, or treats anything,
   and the copy is written to keep it that way:

     - no tool names a condition or tells someone they "have" something
     - results are framed as "what you noticed", never as a score that means
       something clinical
     - every closing note points to a licensed professional for anything that
       worries the person

   Each entry is rendered by assets/discover.js. `id` is a stable UUID derived
   from the slug (uuid5 of https://theraglee.com/discover/<slug>) so members can
   favorite a tool and have it show on the dashboard like any other activity.
   Do not change an id once published; change the slug and the id together.

   Shape shared by every tool
     slug, id, title, description, topic, kind, minutes, tags[], ask
   plus the fields the kind needs (see the header of discover.js).
   ============================================================================= */

