  instr: 'Log the day\'s light and movement in the evening, and add the night\'s sleep the next morning if that is easier.',
  resultNote: 'Look at the nights that went well and read the daytime lines above them. If light and movement were high on those days, you have found something you can act on before dark. If they were not, the answer is elsewhere, and that is useful too.',
