  topic: 'Boundaries', kind: 'sort', minutes: 5, tags: ['boundaries', 'requests', 'commitments'],
  instr: 'Add the actual asks currently on you, then sort each by your honest gut answer.',
  buckets: [{ key: 'yes', label: 'Real yes' }, { key: 'maybe', label: 'Maybe' }, { key: 'no', label: 'Real no' }],
